name: Close Old Bot Discussions

on:
  schedule:
    - cron: '0 0 * * 0' # Run every Sunday at midnight UTC
  workflow_dispatch:

permissions:
  issues: write
  discussions: write

jobs:
  close-old-bot-discussions:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Close old bot discussions
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const daysOld = 30; // Consider discussions older than 30 days as old

            // Fetch discussions
            const discussions = await github.paginate(
              github.rest.discussions.listForRepo,
              {
                owner,
                repo,
                state: 'open',
                per_page: 100
              }
            );

            for (const discussion of discussions) {
              // Check if the discussion is created by a bot
              const author = discussion.author;
              if (author && author.login && author.login.endsWith('[bot]')) {
                const createdAt = new Date(discussion.created_at);
                const now = new Date();
                const diffTime = Math.abs(now - createdAt);
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                if (diffDays > daysOld) {
                  console.log(`Closing old bot discussion: ${discussion.title} (ID: ${discussion.number})`);
                  try {
                    await github.rest.discussions.update({
                      owner,
                      repo,
                      discussion_number: discussion.number,
                      state: 'closed'
                    });
                  } catch (error) {
                    console.error(`Failed to close discussion ${discussion.number}: ${error.message}`);
                  }
                }
              }
            }
